import java.util.List;
import java.util.Map;

/**
 * The MHPCO price list for main items: each main item type carries its own
 * base premium, independent of how many items a policy covers.
 */
public final class MainItemPricing {

    private static final Map<String, Integer> BASE_PREMIUM_PRICE_LIST_IN_G = Map.of(
            "sword", 100,
            "amulet", 60,
            "staff", 80,
            "potion", 40);

    private MainItemPricing() {
    }

    public static boolean isMainItem(String itemType) {
        return BASE_PREMIUM_PRICE_LIST_IN_G.containsKey(itemType);
    }

    public static int basePremium(Item item) {
        return BASE_PREMIUM_PRICE_LIST_IN_G.get(item.type());
    }

    /**
     * The base premium for every main item in a policy: the MHPCO charges each
     * main item at its price-list premium, with no offer for quantity.
     */
    public static int mainItemsBasePremium(List<Item> items) {
        return items.stream()
                .filter(item -> isMainItem(item.type()))
                .mapToInt(MainItemPricing::basePremium)
                .sum();
    }
}
